using System;
using System.Text;
using System.Runtime.InteropServices;
using System.Drawing;

class KeystrokeLogger
{
    [DllImport("user32.dll", SetLastError = true)]
    static extern bool SetConsoleMode(int hConsole, bool bMode);

    [DllImport("user32.dll", SetLastError = true)]
    static extern bool GetConsoleMode(ref int hMode);

    public static void LogKeystrokes()
    {
        bool mode;
        GetConsoleMode(ref mode);
        ConsoleMode = mode;
        ConsoleMode = false;
        Console.WriteLine("Keystroke logged!");
        SetConsoleMode(ConsoleMode, true);
    }
}
```
